// 最大公约数：欧几里得算法（辗转相除法）
int gcd(int a, int b) {
    return b == 0 ? a : gcd(b, a % b);
}

// 最小公倍数 = a / gcd * b（先除后乘防溢出）
int lcm(int a, int b) {
    return a / gcd(a, b) * b;
}

int main() {
    cout << gcd(12, 18) << '\n'; // 6
    cout << lcm(12, 18) << '\n'; // 36
    return 0;
}

