// 埃氏筛：求 [2, n] 内所有素数，O(n log log n)
vector<bool> sieve(int n) {
    vector<bool> isPrime(n + 1, true);
    isPrime[0] = isPrime[1] = false;
    for (int i = 2; i * i <= n; i++) {
        if (isPrime[i]) {
            for (int j = i * i; j <= n; j += i)
                isPrime[j] = false;
        }
    }
    return isPrime;
}

int main() {
    auto p = sieve(50);
    for (int i = 2; i <= 50; i++)
        if (p[i]) cout << i << ' ';
    return 0;
}

#include <bits/stdc++.h>
