// 构建 next 数组：next[i] 表示模式串 [0..i] 的最长相等前后缀长度
vector<int> buildNext(const string& p) {
    int n = p.size();
    vector<int> nxt(n, 0);
    for (int i = 1, j = 0; i < n; i++) {
        while (j > 0 && p[i] != p[j]) j = nxt[j - 1];
        if (p[i] == p[j]) j++;
        nxt[i] = j;
    }
    return nxt;
}

// KMP 匹配：返回模式串 p 在文本 s 中首次出现的位置，无则 -1
int kmp(const string& s, const string& p) {
    if (p.empty()) return 0;
    vector<int> nxt = buildNext(p);
    for (int i = 0, j = 0; i < (int)s.size(); i++) {
        while (j > 0 && s[i] != p[j]) j = nxt[j - 1];
        if (s[i] == p[j]) j++;
        if (j == (int)p.size()) return i - j + 1;
    }
    return -1;
}

int main() {
    string s = "abababca", p = "bab";
    cout << kmp(s, p); // 输出 1
    return 0;
}

public class Singleton {
    // 双检锁（DCL）：线程安全 + 懒加载
    private static volatile Singleton instance;

    private Singleton() {} // 私有构造，禁止外部 new

    public static Singleton getInstance() {
        if (instance == null) {               // 第一次检查
            synchronized (Singleton.class) {  // 加锁
                if (instance == null) {       // 第二次检查
                    instance = new Singleton();
                }
            }
        }
        return instance;
    }
}

import java.util.HashMap;
import java.util.Map;

public class WordCount {
    public static void main(String[] args) {
        String[] words = {"apple", "banana", "apple", "orange", "banana", "apple"};

        Map<String, Integer> count = new HashMap<>();
        for (String w : words) {
            // getOrDefault：键不存在时返回默认值 0
            count.put(w, count.getOrDefault(w, 0) + 1);
        }

        // 遍历输出
        for (Map.Entry<String, Integer> e : count.entrySet()) {
            System.out.println(e.getKey() + ": " + e.getValue());
        }
    }
}

import java.util.*;

public class SortDemo {
    public static void main(String[] args) {
        List<Integer> nums = new ArrayList<>(Arrays.asList(5, 2, 9, 1));

        // 升序
        Collections.sort(nums);
        System.out.println(nums); // [1, 2, 5, 9]

        // 降序（Comparator lambda）
        nums.sort((a, b) -> b - a);
        System.out.println(nums); // [9, 5, 2, 1]

        // 自定义对象：按第一个元素升序
        List<int[]> arr = new ArrayList<>();
        arr.add(new int[]{3, 10});
        arr.add(new int[]{1, 20});
        arr.sort(Comparator.comparingInt(a -> a[0]));
        System.out.println(Arrays.toString(arr.get(0))); // [1, 20]
    }
}

public class StringDemo {
    public static void main(String[] args) {
        String s = "hello";

        // 方式一：StringBuilder 反转
        String reversed = new StringBuilder(s).reverse().toString();
        System.out.println(reversed); // olleh

        // 方式二：双指针判断回文
        String t = "racecar";
        int l = 0, r = t.length() - 1;
        boolean isPalindrome = true;
        while (l < r) {
            if (t.charAt(l) != t.charAt(r)) {
                isPalindrome = false;
                break;
            }
            l++;
            r--;
        }
        System.out.println(isPalindrome); // true
    }
}

import java.util.ArrayList;
import java.util.List;

public class ListDemo {
    public static void main(String[] args) {
        List<String> list = new ArrayList<>();

        // 增
        list.add("Java");
        list.add("C++");
        list.add(0, "Vue");      // 指定位置插入
        System.out.println(list); // [Vue, Java, C++]

        // 查
        System.out.println(list.get(1));           // Java
        System.out.println(list.contains("C++")); // true

        // 改
        list.set(2, "Python");
        System.out.println(list); // [Vue, Java, Python]

        // 删
        list.remove("Vue");
        list.remove(0);
        System.out.println(list); // [Python]
    }
}

// 防抖：触发后 delay 毫秒内无再次触发才执行
// 适用：搜索输入、窗口 resize
function debounce(fn, delay = 300) {
  let timer = null
  return function (...args) {
    if (timer) clearTimeout(timer)
    timer = setTimeout(() => {
      fn.apply(this, args)
      timer = null
    }, delay)
  }
}

// 使用示例：输入框实时搜索
const handleSearch = debounce((kw) => {
  console.log('搜索：', kw)
}, 500)

// 节流：固定间隔内最多执行一次
// 适用：滚动监听、按钮防连点
function throttle(fn, interval = 300) {
  let last = 0
  return function (...args) {
    const now = Date.now()
    if (now - last >= interval) {
      last = now
      fn.apply(this, args)
    }
  }
}

// 使用示例：滚动时更新位置
const onScroll = throttle(() => {
  console.log('scrollY:', window.scrollY)
}, 200)
window.addEventListener('scroll', onScroll)

// 深拷贝：递归复制对象/数组，WeakMap 解决循环引用
function deepClone(obj, cache = new WeakMap()) {
  if (obj === null || typeof obj !== 'object') return obj
  if (cache.has(obj)) return cache.get(obj)

  const result = Array.isArray(obj) ? [] : {}
  cache.set(obj, result)

  for (const key of Object.keys(obj)) {
    result[key] = deepClone(obj[key], cache)
  }
  return result
}

// 使用示例
