const copy = deepClone(original)
copy.nested.ok = false
console.log(original.nested.ok) // true，原对象不受影响

// 数组去重的三种常用写法
const arr = [1, 2, 2, 3, 4, 4, 5]

// 1. Set（最简单）
const unique1 = [...new Set(arr)]

// 2. filter + indexOf（保留首次出现位置）
const unique2 = arr.filter((v, i) => arr.indexOf(v) === i)

// 3. 对象键值标记（最快）
const seen = {}
const unique3 = arr.filter((v) =>
  seen.hasOwnProperty(v) ? false : (seen[v] = true)
)

console.log(unique1, unique2, unique3) // [1,2,3,4,5] ×3

// 基于 Promise 的 fetch 封装：统一处理 JSON、超时与错误
async function request(url, options = {}) {
  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(), 10000) // 10s 超时

  try {
    const res = await fetch(url, {
      ...options,
      headers: { 'Content-Type': 'application/json', ...options.headers },
      signal: controller.signal
    })
    if (!res.ok) throw new Error('HTTP ' + res.status)
    return await res.json()
  } finally {
    clearTimeout(timer)
  }
}

// 使用示例
request('/api/questions', { method: 'GET' })
  .then((data) => console.log(data))
  .catch((err) => console.error(err))

// localStorage 工具：自动 JSON 序列化 + 异常保护
const store = {
  get(key, defaultValue = null) {
    try {
      const raw = localStorage.getItem(key)
      return raw === null ? defaultValue : JSON.parse(raw)
    } catch {
      return defaultValue // 解析失败返回默认值
    }
  },
  set(key, value) {
    try {
      localStorage.setItem(key, JSON.stringify(value))
      return true
    } catch {
      return false // 超出容量或禁用存储时静默失败
    }
  },
  remove(key) {
    localStorage.removeItem(key)
  }
}

// 使用示例
store.set('user', { name: 'xy', level: 1 })
console.log(store.get('user', {}))
store.remove('user')
